    	protected TButton closeButton;	protected TMP_InputField levelInputFieldTMP;	protected TButton jumpLevelBtn;	protected TButton addItemsBtn;	protected TextMeshProUGUI uidInfo;	protected TextMeshProUGUI abInfo;	protected TButton buttonA;	protected TButton buttonB;	protected TButton deleteBtn;	protected TButton addCoinBtn;	protected TButton jumpInfinitLevelBtn;	protected TMP_InputField infinitLevelInputFieldTMP;	protected TMP_InputField winStreakInputField;	protected TButton winStreakBtn;	protected TMP_InputField timeImput;	protected TButton setTimeBtn;	protected TButton resetTimebySystem;	protected TextMeshProUGUI curDateTime;	protected TMP_InputField goldtreeNumInputField;	protected TButton goldTreeBtn;	protected TMP_InputField leagueInputField;	protected TButton leagueBtn;
    protected override void OnBindCompsAndEvents() 
